import FOOTER from "@/components/FOOTER";
import MENU from "@/components/MENU";
import { concertsByYear } from "@/lib/defs";
import { Metadata } from "next";
import Link from "next/link";
import Script from "next/script";
import { safeJsonLd } from "@/lib/jsonld";

export const metadata: Metadata = {
  title: "Concerts",
  description:
    "A chronological list of concerts and live performances attended by Jasper Mayone.",
  alternates: {
    canonical: "https://jaspermayone.com/concerts",
  },
};

// Flatten all concerts for the schema
const allConcerts = concertsByYear.flatMap((yearGroup) =>
  yearGroup.concerts.map((concert) => ({
    ...concert,
    year: yearGroup.year,
  }))
);

const concertsPageSchema = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebPage",
      "@id": "https://jaspermayone.com/concerts#webpage",
      url: "https://jaspermayone.com/concerts",
      name: "Concerts - Jasper Mayone",
      description:
        "A chronological list of concerts and live performances attended by Jasper Mayone.",
      isPartOf: {
        "@id": "https://jaspermayone.com/#website",
      },
      about: {
        "@id": "https://jaspermayone.com/#person",
      },
      mainEntity: {
        "@id": "https://jaspermayone.com/concerts#concert-list",
      },
      breadcrumb: {
        "@type": "BreadcrumbList",
        "@id": "https://jaspermayone.com/concerts#breadcrumb",
        itemListElement: [
          {
            "@type": "ListItem",
            position: 1,
            name: "Home",
            item: "https://jaspermayone.com",
          },
          {
            "@type": "ListItem",
            position: 2,
            name: "Concerts",
            item: "https://jaspermayone.com/concerts",
          },
        ],
      },
    },
    {
      "@type": "ItemList",
      "@id": "https://jaspermayone.com/concerts#concert-list",
      name: "Concerts Attended by Jasper Mayone",
      description:
        "A chronological list of live music performances attended by Jasper Mayone",
      numberOfItems: allConcerts.length,
      itemListElement: allConcerts.map((concert, index) => ({
        "@type": "ListItem",
        position: index + 1,
        item: {
          "@type": "MusicEvent",
          name: `${concert.headliner}${concert.tour ? ` - ${concert.tour}` : ""}`,
          performer: {
            "@type": "MusicGroup",
            name: concert.headliner,
          },
          ...(concert.date && { startDate: concert.date }),
          ...(concert.venue && {
            location: {
              "@type": "Place",
              name: concert.venue,
            },
          }),
          ...(concert.openers &&
            concert.openers.length > 0 && {
              subEvent: concert.openers.map((opener) => ({
                "@type": "MusicEvent",
                name: opener,
                performer: {
                  "@type": "MusicGroup",
                  name: opener,
                },
              })),
            }),
          ...(concert.setlist && { url: concert.setlist }),
        },
      })),
    },
  ],
};

export default function Concerts() {
  // Sort years in descending order and concerts within each year by date (newest first)
  const sortedConcerts = concertsByYear
    .map((yearGroup) => ({
      ...yearGroup,
      concerts: yearGroup.concerts.toSorted((a, b) => {
        // Sort by date in descending order (newest first)
        const dateA = a.date ? new Date(a.date).getTime() : 0;
        const dateB = b.date ? new Date(b.date).getTime() : 0;
        return dateB - dateA;
      }),
    }))
    .sort((a, b) => b.year - a.year); // Sort years in descending order

  return (
    <>
      <Script
        id="concerts-schema"
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: safeJsonLd(concertsPageSchema),
        }}
      />
      <div className="flex min-h-screen flex-col">
        <MENU pageFirstWord="Concerts" />
        <main className="flex-1">
          <div className="mx-5 mt-4 mb-4">
            <h1
              className="mb-4 text-xl font-semibold text-zinc-800 dark:text-white"
              style={{ fontFamily: "var(--font-balgin)" }}
            >
              Concerts I&apos;ve Attended
            </h1>

            <p className="mb-6 text-zinc-600 dark:text-white/70">
              A running list of live shows and concerts I&apos;ve been to over
              the years.
            </p>

            <div className="space-y-8">
              {sortedConcerts.map((yearGroup) => (
                <div key={yearGroup.year}>
                  <h2
                    className="mb-3 text-lg font-semibold text-zinc-900 dark:text-white"
                    style={{ fontFamily: "var(--font-balgin)" }}
                  >
                    {yearGroup.year}
                  </h2>
                  <ul className="space-y-3">
                    {yearGroup.concerts.map((concert) => (
                      <li
                        key={`${yearGroup.year}-${concert.headliner}-${concert.date ?? ""}`}
                        className="border-l-2 border-zinc-300 pl-4 dark:border-zinc-600"
                      >
                        <div className="flex items-start gap-2">
                          <div className="flex-1">
                            <div className="font-medium text-zinc-900 dark:text-white">
                              {concert.headliner}
                            </div>
                            {concert.openers && concert.openers.length > 0 && (
                              <div
                                className="text-sm text-zinc-600 dark:text-zinc-400"
                                style={{ fontFamily: "var(--font-balgin)" }}
                              >
                                with {concert.openers.join(", ")}
                              </div>
                            )}
                            {concert.tour && (
                              <div
                                className="text-sm text-zinc-600 dark:text-zinc-400"
                                style={{ fontFamily: "var(--font-balgin)" }}
                              >
                                {concert.tour}
                              </div>
                            )}
                            {concert.venue && (
                              <div className="text-xs text-zinc-500 dark:text-zinc-500">
                                {concert.venue}
                                {concert.date && ` • ${concert.date}`}
                              </div>
                            )}
                            {concert.setlist && (
                              <div
                                className="mt-1 text-xs"
                                style={{ fontFamily: "var(--font-balgin)" }}
                              >
                                <Link
                                  href={concert.setlist}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  prefetch={false}
                                  className="text-blue-600 hover:underline dark:text-blue-400"
                                >
                                  View Setlist →
                                </Link>
                              </div>
                            )}
                          </div>
                        </div>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </div>
        </main>
        <FOOTER />
      </div>
    </>
  );
}

